import { transform } from "../transform.ts";
const base = { folio: "0.1", issuer: "x", patient: "p", narrative: "" };
const it = (id: string, eff: string, rec: string, payload: any, extra: any = {}) => ({ ...base, id, effective: eff, recorded: rec, payload, ...extra });
const med = (o: any) => ({ type: "med_event", origin: "northgate", ...o });
const items: any[] = [
  it("a", "2024-01-05T10:00:00-06:00", "2024-01-05T10:00:00-06:00", { m: med({ med_id: "L1", action: "start", drug: { name: "metformin hydrochloride 500 MG Oral Tablet", rxnorm: "861007" }, dose: { value: 2, unit: "tablet" }, frequency: "BID" }) }),
  it("b", "2024-03-01T10:00:00-06:00", "2024-03-01T10:00:00-06:00", { m: med({ med_id: "L1", action: "hold", drug: { name: "metformin hydrochloride 500 MG Oral Tablet" }, reason_text: "holding for contrast CT", review_on: "2024-03-10" }) }),
  it("c", "2024-03-02T03:30:00Z", "2024-03-02T03:31:00Z", { m: med({ med_id: "L2", action: "start", drug: { name: "Ventolin HFA 90 MCG/ACTUAT Metered Dose Inhaler" }, dose: { value: 2, unit: "puffs" }, frequency: "PRN" }),
    m2: med({ med_id: "L3", action: "start", drug: { name: "quetiapine 50 MG Oral Tablet" }, dose: { value: 50, unit: "mg" }, frequency: "QHS", restricted: "BH" }),
    m3: med({ med_id: "L4", action: "start", drug: { name: "amlodipine 5 MG / benazepril hydrochloride 10 MG Oral Capsule" }, dose: { value: 1, unit: "capsule" }, frequency: "QD" }) }),
  it("d", "2024-04-01", "2024-04-01T09:00:00-05:00", { m: med({ med_id: "L3", action: "stop", drug: { name: "quetiapine 50 MG Oral Tablet" }, stop_reason: "adverse_reaction", reason_text: "weight gain" }) }),
  it("e", "2024-04-02", "2024-04-02T09:00:00-05:00", { p: { type: "problem_event", problem_id: "P1", action: "add", description: "Urticaria due to amoxicillin", icd10cm: "L50.0" },
    p2: { type: "problem_event", problem_id: "P2", action: "add", description: "Adverse effect of penicillins, initial encounter", icd10cm: "T36.0X5A" },
    m: med({ med_id: "L5", action: "stop", drug: { name: "amoxicillin 500 MG Oral Capsule" }, stop_reason: "adverse_reaction" }),
    p3: { type: "problem_event", problem_id: "P3", action: "add", description: "Alcohol use disorder, moderate", icd10cm: "F10.20", onset: { date: "2019", precision: "year" } } }),
  it("f", "2024-05-01", "2024-05-01T09:00:00-05:00", { p: { type: "problem_event", problem_id: "P3", action: "resolve", description: "Alcohol use disorder, in remission", icd10cm: "F10.21" } }),
  it("g", "2024-05-02", "2024-05-02T09:00:00-05:00", { x: { type: "chart_correction", voided_items: ["c"], reason: "entry_error" } }, { retracts: ["c"] }),
];
console.log(JSON.stringify(transform(items as any, "2024-03-01"), null, 1).slice(0, 3000));
console.log(JSON.stringify(transform(items as any, "2024-05-01"), null, 1));
console.log(JSON.stringify(transform(items as any, "2024-06-01").medications.map(m => m.ingredient)));
EOF
